// ============================================================================
// File: tb/v3/tb_ch03_fir.v
// Module: tb_ch03_fir
// Description:
//   Cycle-accurate, bit-exact testbench for rtl/v3/ch03_fir_filter.v.
//   - Reads cycle-by-cycle stimulus from tb_ch03_fir_stim.txt.
//   - Reads expected values from tb_ch03_fir_expected.txt (generated by Python twin).
//   - Compares bit-for-bit and cycle-for-cycle:
//     * sink_ready
//     * source_valid
//     * source_data (when source_valid == 1)
//     * dut.state (internal FSM state)
//     * dut.step (internal folded step)
//   - Fully compatible with `iverilog -g2012 -Wall`.
// ============================================================================

`timescale 1ns/1ps

module tb_ch03_fir;

    parameter DATA_WIDTH  = 16;
    parameter COEFF_WIDTH = 16;
    parameter ACC_WIDTH   = 40;

    reg clk = 0;
    always #10 clk = ~clk; // 50 MHz clock (20 ns period)

    reg                         rst_n;
    reg                         bypass;
    reg                         sink_valid;
    reg  signed [DATA_WIDTH-1:0] sink_data;
    wire                        sink_ready;

    wire                        source_valid;
    reg                         source_ready;
    wire signed [DATA_WIDTH-1:0] source_data;

    // Instantiate DUT
    ch03_fir_filter #(
        .DATA_WIDTH(DATA_WIDTH),
        .COEFF_WIDTH(COEFF_WIDTH),
        .ACC_WIDTH(ACC_WIDTH)
    ) dut (
        .clk(clk),
        .rst_n(rst_n),
        .bypass(bypass),
        .sink_valid(sink_valid),
        .sink_ready(sink_ready),
        .sink_data(sink_data),
        .source_valid(source_valid),
        .source_ready(source_ready),
        .source_data(source_data)
    );

    integer stim_fd;
    integer exp_fd;
    integer cycle_idx;
    integer errors;

    // Stimulus variables from file:
    // format: rst_n bypass sink_valid sink_data_hex source_ready
    integer stim_rst_n;
    integer stim_bypass;
    integer stim_s_vld;
    reg [DATA_WIDTH-1:0] stim_s_dat;
    integer stim_m_rdy;

    // Expected variables from file:
    // format: cycle rst_n bypass sink_valid sink_data source_ready sink_ready source_valid source_data state step
    integer exp_c;
    integer exp_rst_n;
    integer exp_bypass;
    integer exp_s_vld;
    reg [DATA_WIDTH-1:0] exp_s_dat;
    integer exp_m_rdy;
    integer exp_s_rdy;
    integer exp_m_vld;
    reg [DATA_WIDTH-1:0] exp_m_dat;
    integer exp_state;
    integer exp_step;

    initial begin
        rst_n        = 0;
        bypass       = 0;
        sink_valid   = 0;
        sink_data    = {DATA_WIDTH{1'b0}};
        source_ready = 0;
        cycle_idx    = 0;
        errors       = 0;

        // Open stimulus file
        stim_fd = $fopen("verify_v3/tb_ch03_fir_stim.txt", "r");
        if (stim_fd == 0) stim_fd = $fopen("tb_ch03_fir_stim.txt", "r");
        if (stim_fd == 0) begin
            $display("ERROR: Cannot open tb_ch03_fir_stim.txt");
            $finish;
        end

        // Open expected trace file
        exp_fd = $fopen("verify_v3/tb_ch03_fir_expected.txt", "r");
        if (exp_fd == 0) exp_fd = $fopen("tb_ch03_fir_expected.txt", "r");
        if (exp_fd == 0) begin
            $display("ERROR: Cannot open tb_ch03_fir_expected.txt");
            $finish;
        end

        $display("=== STARTING CH03 FIR CYCLE-BY-CYCLE VERIFICATION ===");

        // Align to falling edge before starting cycle-by-cycle verification
        @(negedge clk);

        // Run cycle by cycle
        while ($fscanf(stim_fd, "%d %d %d %h %d\n",
                       stim_rst_n, stim_bypass, stim_s_vld, stim_s_dat, stim_m_rdy) == 5 &&
               $fscanf(exp_fd, "%d %d %d %d %h %d %d %d %h %d %d\n",
                       exp_c, exp_rst_n, exp_bypass, exp_s_vld, exp_s_dat, exp_m_rdy,
                       exp_s_rdy, exp_m_vld, exp_m_dat, exp_state, exp_step) == 11) begin

            // 1. Drive inputs during clock low phase (at negedge clk)
            rst_n        = (stim_rst_n != 0) ? 1'b1 : 1'b0;
            bypass       = (stim_bypass != 0) ? 1'b1 : 1'b0;
            sink_valid   = (stim_s_vld != 0) ? 1'b1 : 1'b0;
            sink_data    = stim_s_dat;
            source_ready = (stim_m_rdy != 0) ? 1'b1 : 1'b0;

            // 2. Allow combinational outputs to settle before posedge clk
            #1;

            // 3. Sample and check combinational output (sink_ready) BEFORE the clock edge
            if (sink_ready !== ((exp_s_rdy != 0) ? 1'b1 : 1'b0)) begin
                $display("[FAIL] Cycle %0d: sink_ready mismatch (got %b, exp %0d)",
                         cycle_idx, sink_ready, exp_s_rdy);
                errors = errors + 1;
            end

            // 4. Wait for rising clock edge where registers update
            @(posedge clk);
            #1;

            // 5. Sample and check registered outputs AFTER posedge clk
            // Check source_valid
            if (source_valid !== ((exp_m_vld != 0) ? 1'b1 : 1'b0)) begin
                $display("[FAIL] Cycle %0d: source_valid mismatch (got %b, exp %0d)",
                         cycle_idx, source_valid, exp_m_vld);
                errors = errors + 1;
            end

            // Check source_data when valid
            if (source_valid && (source_data !== exp_m_dat)) begin
                $display("[FAIL] Cycle %0d: source_data mismatch (got 0x%04x (%0d), exp 0x%04x (%0d))",
                         cycle_idx, source_data, $signed(source_data), exp_m_dat, $signed(exp_m_dat));
                errors = errors + 1;
            end

            // Check internal state
            if (dut.state !== exp_state[1:0]) begin
                $display("[FAIL] Cycle %0d: dut.state mismatch (got %0d, exp %0d)",
                         cycle_idx, dut.state, exp_state);
                errors = errors + 1;
            end

            // Check internal step when in S_CALC
            if (dut.state == 2'd1 && dut.step !== exp_step[3:0]) begin
                $display("[FAIL] Cycle %0d: dut.step mismatch (got %0d, exp %0d)",
                         cycle_idx, dut.step, exp_step);
                errors = errors + 1;
            end

            cycle_idx = cycle_idx + 1;

            // 6. Return to falling edge for next stimulus cycle
            @(negedge clk);
        end

        $fclose(stim_fd);
        $fclose(exp_fd);

        $display("Simulation completed %0d cycles.", cycle_idx);
        $display("Total comparison errors: %0d", errors);

        if (errors == 0 && cycle_idx >= 200) begin
            $display("=== [PASS] CH03 FIR MATCHED PYTHON TWIN BIT-FOR-BIT AND CYCLE-FOR-CYCLE ON %0d CYCLES ===", cycle_idx);
        end else begin
            $display("=== [FAIL] CH03 FIR FAILED WITH %0d ERRORS ===", errors);
        end

        $finish;
    end

endmodule
